def preserve_existing_package_data(apps, schema_editor):
    GroupSize = apps.get_model("packages", "GroupSize")
    TravelPackage = apps.get_model("packages", "TravelPackage")
    PackageDeparture = apps.get_model("packages", "PackageDeparture")

    # Create the default group sizes.
    sizes = {
        "small": 10,
        "medium": 20,
        "large": 40,
    }

    for name, capacity in sizes.items():
        GroupSize.objects.get_or_create(
            name=name,
            defaults={"capacity": capacity},
        )

    # Preserve existing group package types.
    for package in TravelPackage.objects.filter(trip_mode="group"):
        if package.traveller_type in ("student_group", "open_group"):
            package.group_type = package.traveller_type
        else:
            package.group_type = "open_group"

        package.save(update_fields=["group_type"])

    # Preserve group departure seat information.
    # Private departures do not use shared seat capacity.
    for departure in PackageDeparture.objects.select_related("package").all():
        if departure.package.trip_mode == "private":
            departure.group_size = None
            departure.total_seats = None
            departure.available_seats = None
            departure.save(
                update_fields=[
                    "group_size",
                    "total_seats",
                    "available_seats",
                ]
            )
        else:
            total = departure.total_seats or 10

            if total <= 10:
                size_name = "small"
            elif total <= 20:
                size_name = "medium"
            else:
                size_name = "large"

            departure.group_size = GroupSize.objects.get(name=size_name)

            if departure.total_seats is None:
                departure.total_seats = departure.group_size.capacity

            if departure.available_seats is None:
                departure.available_seats = departure.total_seats

            departure.save(
                update_fields=[
                    "group_size",
                    "total_seats",
                    "available_seats",
                ]
            )


def populate_booking_references(apps, schema_editor):
    PackageBooking = apps.get_model("packages", "PackageBooking")

    for booking in PackageBooking.objects.filter(
        booking_reference__isnull=True
    ).iterator():
        booking.booking_reference = uuid.uuid4()
        booking.save(update_fields=["booking_reference"])


